class Planet {
	constructor(position, radius, color = '#FFFFFF', showOrbit = true) {
		this.position = position;
		this.radius = radius;
		this.color = color;
		this.relativePosition = createVector(0, 0);
		this.dashes = [];
		this.turnSpeed = random(1, 5);
		this.turnProgress = 0;
		this.visited = false;
		this.showOrbit = showOrbit;

		for (let i = 0; i < 5; i++) {
			this.dashes.push(random(10, 20));
			this.dashes.push(random(20, 30));
		}
	}

	calcRelativePosition(playerPos) {
		this.relativePosition = p5.Vector.sub(this.position, playerPos);
	}

	draw() {
		this.turnProgress += this.turnSpeed * deltaTime * 0.001;
		stroke(this.color);
		noFill();
		drawingContext.setLineDash([]);

		fill(backgroundColor);
		beginShape();
		for (let i = 0; i < 1000; i++) {
			let progress = i / 1000;
			let x = this.radius * 0.66 * cos(progress * TWO_PI);
			let y = this.radius * 0.66 * sin(progress * TWO_PI);
			let n = map(noise(x * 0.02 + abs(this.position.x + 1000), y * 0.02 + abs(this.position.y + 1000), sin(frameCount * 0.002) + 1), 0, 1, 0.5, 1);
			vertex(x * n + this.relativePosition.x, y * n + this.relativePosition.y);
		}
		endShape();


		drawingContext.setLineDash(this.dashes);

		beginShape();
		for (let i = 0; i < 1000; i++) {
			let progress = i / 1000;
			let x = this.radius * 0.4 * cos(progress * TWO_PI);
			let y = this.radius * 0.4 * sin(progress * TWO_PI);
			let n = map(noise(x * 0.02 + abs(this.position.x + 1000), y * 0.02 + abs(this.position.y + 1000), frameCount * 0.001), 0, 1, 0.2, 1);
			vertex(x * n + this.relativePosition.x, y * n + this.relativePosition.y);
		}
		endShape();
		noFill();

		stroke(lerpColor(color(this.color), color(backgroundColor), 0.5));

		let lineLength = 2 * PI * this.radius / 50;
		drawingContext.setLineDash([lineLength, lineLength]);
		if(this.showOrbit) {
			circle(this.relativePosition.x, this.relativePosition.y, this.radius * 2);
		}
	}
}

