/*
	contribution to this weeks coding challenge (by @Sablerath), with the prompt 'falling':
	Originally, I struggeled to come up with an idea that incorperated falling.
	I didnt want to go with a straight forward way like leaves falling from trees or objects falling in a gravity simulation
	After some thinking i settled on this a bit more abstract of falling, where a body is falling endlessly through space,
	where the player has no control over the the direction but rather can only watch as they fly past planets/asteroides
*/

let rocketImg;
let playerRotation = 0;
let rotSpeed = 0;
let oldAngle = 0;

let planets = [];
let smallPlanet;
let playerPos;
let playerVel;

let targetPlanet;
let entryAngle = 0;
let currentDeltaAngle = 0;
let targetDeltaAngle = 0;
let lastDistance = 0;
let orbit = false;

let points = [];
let spacingOffset = 0;

let stars = [];

const backgroundColor = '#000717';

const speed = 150;

let currentZoom = 1;
let zoom = 1;

function setup() {
	describe(`contribution to this weeks coding challenge (by @Sablerath), with the prompt 'falling':
	Originally, I struggeled to come up with an idea that incorperated falling.
	I didnt want to go with a straight forward way like leaves falling from trees or objects falling in a gravity simulation
	After some thinking i settled on this a bit more abstract of falling, where a body is falling endlessly through space,
	where the player has no control over the the direction but rather can only watch as they fly past planets/asteroides`);

	rocketImg = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/rocket.png');
	imageMode(CENTER);

	let cnv =  createCanvas(windowWidth, windowHeight);
	cnv.mouseWheel(changeSize);

	playerPos = createVector(0, 0);
	playerVel = createVector(1, 0);
	planets.push(new Planet(createVector(300, -75), 75, '#FFFFFF'));
	smallPlanet = new Planet(createVector(0, 0), 75, '#FFFFFF', false);
	targetPlanet = planets[0];
	for(let i = 0; i < 400; i++) {
		let starSize = random(1, 5);
		let starX = random(width * 2) - width / 2;
		let starY = random(height * 2) - height / 2;
		let perspectiveMultiplier = random(0, 0.1);
		stars.push({
			size: starSize,
			x: starX,
			y: starY,
			perspectiveMult: perspectiveMultiplier,
		});
	}
}

function draw() {
	//draw background
	background(backgroundColor);

	for(let i = 0; i < stars.length; i++) {
		strokeWeight(stars[i].perspectiveMult * 50);
		stroke(255);
		point(stars[i].x - playerPos.x * stars[i].perspectiveMult, stars[i].y - playerPos.y * stars[i].perspectiveMult);
	}

	strokeWeight(2);
	//translate and scale canvas
	translate(width / 2, height / 2);
	currentZoom = lerp(currentZoom, zoom, deltaTime * 0.0005);
	scale(currentZoom);

	//update position
	playerVel.normalize();
	playerPos.add(p5.Vector.mult(playerVel, speed * deltaTime * 0.001));

	//update velocity
	let distToTargetPlanet = dist(playerPos.x, playerPos.y, targetPlanet.position.x, targetPlanet.position.y);
	if(lastDistance <= distToTargetPlanet && distToTargetPlanet <= targetPlanet.radius * 1.1 && !targetPlanet.visited) {
		orbit = true;
		targetPlanet.visited = true;
		let entryAngle = degrees(p5.Vector.angleBetween(targetPlanet.relativePosition, createVector(-1, 0)));
		targetDeltaAngle = random(90, 135);
		currentDeltaAngle = 0;
	}
	lastDistance = distToTargetPlanet;

	let minDistance = distToTargetPlanet;
	for(let i = 0; i < planets.length; i++) {
		let newDist = dist(playerPos.x, playerPos.y, planets[i].position.x, planets[i].position.y);
		minDistance = min(minDistance, newDist);
	}

	let zoomVal = 1 - min(max(minDistance / 600, 0),1);
	let scaledZoomVal = -(Math.cos(Math.PI * zoomVal) - 1) / 2;
	zoom = scaledZoomVal * 5 + 3;

	if(orbit) {
		let initialAngle = p5.Vector.angleBetween(playerVel, targetPlanet.relativePosition);
		playerVel = targetPlanet.relativePosition.copy();

		playerVel.rotate(radians(90 * -Math.sign(initialAngle)));

		playerVel.normalize();

		let diffToPlanet = p5.Vector.sub(playerPos, targetPlanet.position);
		diffToPlanet.setMag(targetPlanet.radius);
		playerPos = p5.Vector.add(targetPlanet.position, diffToPlanet);
		let newAngle = p5.Vector.angleBetween(playerVel, targetPlanet.relativePosition);
		currentDeltaAngle += abs(degrees(newAngle - initialAngle));
		rotSpeed -= radians(currentDeltaAngle) * 0.01 * -Math.sign(initialAngle);

		if(currentDeltaAngle >= targetDeltaAngle) {
			orbit = false;
			createNewPlanet();
			getNextPlanet();

			let _wG_1 = 0; while ((planets.length > 2) && ++_wG_1 < 20000) {
				planets.shift();
			}
		}
	}

	//update and draw planets
	for(let i = 0; i < planets.length; i++) {
		planets[i].calcRelativePosition(playerPos);
		planets[i].draw();
	}

	//draw player trail
	points.push(playerPos.copy());
	let _wG_2 = 0; while ((points.length > 250) && ++_wG_2 < 20000) {
		let spacing = 0;
		let _wG_3 = 0; while ((spacing < 40 && points.length > 0) && ++_wG_3 < 20000) {
			spacing += dist(points[0].x, points[0].y, points[1].x, points[1].y);
			points.shift();
		}
		let diff = spacing - 40;
		let newPointDir = p5.Vector.sub(points[1], points[0]);
		newPointDir.normalize();
		let newPoint = p5.Vector.add(points[0], newPointDir.mult(diff));
		points.unshift(newPoint);
	}

	stroke(255);
	drawingContext.setLineDash([20, 20]);
	beginShape();
	for(let i = 0; i < points.length; i++) {
		vertex(points[i].x - playerPos.x, points[i].y - playerPos.y);
	}
	endShape();

	//draw player
	noStroke();
	fill('#FFFFFF');
	scale(0.5);
	playerRotation += deltaTime * 0.001 * rotSpeed;
	rotate(playerRotation);
	smallPlanet.draw();
	//image(rocketImg, 0, 0);
}

function getNextPlanet() {
	for(let i = 0; i < planets.length; i++) { 
		if(!planets[i].visited) {
			targetPlanet = planets[i];
		}
	}
}

function createNewPlanet() {
	let newPlanetDistance = random(500, 1000);
	let planetPos = p5.Vector.add(playerPos, p5.Vector.mult(playerVel, newPlanetDistance));
	let planetRadius = random(50, 150);
	let planetOffset = p5.Vector.rotate(playerVel, (random() < 0.5) ? radians(90) : radians(-90));
	planetPos.add(p5.Vector.mult(planetOffset, planetRadius));
	planets.push(new Planet(planetPos, planetRadius, color('#FFFFFF')));
}

